#!/usr/bin/env python3
"""Render concrete report from saved observations, never a fabricated conclusion."""
import json
import datetime
from preflight import preflight
from protocol import HERE, ROOT, load, sha
from analyze import analyze
from migration import migration
from final_items import items

def number(value, digits=3):
    return 'not measured' if value is None else f'{value:.{digits}f}'

def report():
    result = analyze()
    migration()
    for name, key in [('search-accounting.json', 'search_accounting'), ('frontend-smoke.json', 'frontend_smoke'), ('presentation-persistence.json', 'presentation_persistence'), ('shipping-explanation-cap.json', 'shipping_explanation_cap'), ('source-differential-verification.json', 'source_tree_differential')]:
        result[key] = load(HERE / name) if (HERE / name).exists() else {'status': 'not measured'}
    if (HERE / 'evidence-manifest.json').exists():
        result['hashes']['evidence_manifest'] = sha(HERE / 'evidence-manifest.json')
        result['evidence_manifest'] = 'scripts/eight-cell-operational-successor/evidence-manifest.json'
    if (HERE / 'terminal-validation.json').exists():
        result['terminal_validation'] = load(HERE / 'terminal-validation.json')
    result['sleep_prevention'] = load(HERE / 'sleep-prevention.json')
    result['baseline_execution_proof'] = preflight()
    lock = load(HERE / 'audit-lock.json')
    result['pre_measurement_chronology_valid'] = all(datetime.datetime.fromisoformat(v['completed_at']) < datetime.datetime.fromisoformat(lock['locked_at']) for v in result['baseline_execution_proof'].values()) and datetime.datetime.fromisoformat(lock['locked_at']) < datetime.datetime.fromisoformat(load(HERE / 'execution.json')['started_at'])
    result['prior_invalid_audit_preserved'] = True
    result['prior_raw_files_verified'] = load(HERE / 'baseline.json')['prior_raw_manifest_verified']
    result['qualification_valid'] = result['classification'] != 'D'
    result['publication_ready'] = result['status'] == 'complete' and bool(result['final_checks']) and all(v['exit_code'] == 0 and v['required_test_executed'] for v in result['final_checks'].values()) and result['pre_measurement_chronology_valid'] and result['search_accounting'].get('scientific_match_to_real_HTTP') is True and result['frontend_smoke'].get('exit_code') == 0 and 'evidence_manifest' in result['hashes']
    result['required_final_items'] = items(result)
    (ROOT / 'docs/eight-cell-operational-budget-successor.json').write_text(json.dumps(result, indent=2) + '\n')
    lines = ['# Eight-Cell Operational + Request-Budget Clean Successor', '', f"**{result['decision']} ({result['classification']}).** Status: {result['status']}. Production Cell cap remains **six**. No product promotion or request-policy change is applied.", '', result['scope'] + '.', '', 'This preregistered audit compares paired 6C/8C W1 requests on the minimum certified reference. A positive result applies only to the exact tested layouts/settings/runtime; neither larger tiers nor historical timing can rescue Profile A.', '', '## Baseline and frozen contract', '', f"Starting baseline: `{result['baseline']['head']}`, branch `{result['baseline']['branch']}`, VERSION `{result['baseline']['version']}`, prior audit documentation and scripts already uncommitted. The recorded status and diff are in baseline.json. Prior invalid audit reports, locks, manifests, scripts and raw archives remain byte-for-byte preserved.", '', '| Artifact | SHA256 / reference |', '|---|---|']
    lines += ['', 'Both required baseline E2Es actually executed with ATOM_REAL_E2E=1 before this lock and any successor measurement. The guard validates named Playwright JSON records, passed results and counts; it rejects skipped, zero-test, missing-opt-in and mismatched-test data. The [prior invalid audit](eight-cell-operational-budget-audit.html) remains D unchanged.', '', '|Baseline test|Discovered|Executed|Passed|Failed|Skipped|Completed UTC|', '|---|---:|---:|---:|---:|---:|---|']
    for name, value in result['baseline_execution_proof'].items():
        proof = value['execution_guard']
        lines.append(f"|{name}|{proof['discovered']}|{proof['executed']}|{proof['passed']}|{proof['failed']}|{proof['skipped']}|{value['completed_at']}|")
    lines += ['', f"Lock frozen at {lock['locked_at']}; chronology machine-verified: {result['pre_measurement_chronology_valid']}.", '', '| Artifact | SHA256 / reference |', '|---|---|']
    for label, field in [('Audit lock', 'audit_lock'), ('Domain manifest', 'domain_manifest'), ('Run plan', 'run_plans')]:
        lines.append(f"| {label} | `{result['hashes'][field]}` |")
    lines += ['| Evidence manifest | [Manifest](../scripts/eight-cell-operational-successor/evidence-manifest.json), with final digest in [SHA256 file](../scripts/eight-cell-operational-successor/evidence-manifest.sha256) |', '', 'Raw streamed bodies, ledgers, sampler/async traces and logs stay outside Git in `/tmp/atom-eight-cell-operational-successor`. The tracked index identifies every retained raw artifact by path/logical ID, SHA256, byte size, category and group; a local compressed archive retains the indexed evidence. No historical evidence is removed.', '', '## Shipping versus audit binary', '', 'The audit uses a disposable source copy and the unchanged production Dockerfile. The only production-source difference is `MaxNetworkTowers = 6` → `8` in that copy. The existing Auto metadata consequently reports eight for the audit binary. Normal source and shipping builds remain six. Recommendation remains five and Measurement Validation remains six. No production override/environment switch is added.', '', '| Build | Image identity | Binary SHA256 |', '|---|---|---|']
    for kind, value in result['binary_differential']['images'].items():
        lines.append(f"| {kind} | `{value['image_id']}` | `{value['binary_sha256']}` |")
    lines += ['', 'Both binaries use Go1.26.6, Linux/arm64, CGO disabled, identical release flags and pinned compiler/runtime bases. [Machine-readable differential](../scripts/eight-cell-operational-successor/binary-differential.json) records source/build metadata. The [complete copied-source comparison](../scripts/eight-cell-operational-successor/source-differential-verification.json) checks 373 copied files across backend/frontend, Dockerfile and VERSION; only the cap constant differs. Host Go quality checks are separate from qualification timing.', '', 'Before every batch, existing Auto diagnostics and Docker/cgroup inspection verify effective CPU2, GOMAXPROCS2, hard memory4GiB, workers1, queue16, global/per-client RF slots2/1, deadline60s, budget20/60s and exact dataset hashes/counts. No GOMAXPROCS, GC, memory, worker, admission or limiter tuning is applied.', '', '### Normal shipping cap proof', '', '| Endpoint | Six | Seven | Eight | Exact rejection body |', '|---|---:|---:|---:|---|']
    proof = result['shipping_cap_proof']
    if proof:
        endpoints = sorted({r['endpoint'] for r in proof[0]['responses']})
        for endpoint in endpoints:
            responses = {r['input_cells']: r for r in proof[0]['responses'] if r['endpoint'] == endpoint}
            lines.append(f"| `{endpoint}` | {responses[6]['status']} | {responses[7]['status']} | {responses[8]['status']} | `{responses[8]['body']}` |")
    if result['shipping_explanation_cap'].get('passed'):
        responses = {r['input_cells']: r for r in result['shipping_explanation_cap']['responses']}
        lines.append(f"| `/api/explain-network-cell` | {responses[6]['status']} | {responses[7]['status']} | {responses[8]['status']} | `{responses[8]['body']}` |")
    lines += ['', '## Dataset and paired layouts', '', 'Exact `ankara-open-planning` version `2026.07`: 161,784 indexed footprint parts, 936,651 vertices, 451 inventory Cells. Frozen GeoJSON identities:', '']
    for filename, digest in result['dataset']['sha256'].items():
        lines.append(f'- `{filename}`: `{digest}`')
    lines += ['', 'All eight paired layouts are copied byte-for-byte from the prior manifest. Every original six ID/order and the same appended two IDs are preserved; no Cell reselection occurs. The [domain manifest](../scripts/eight-cell-operational-successor/domain-manifest.json) freezes coordinates, profiles, relative geometry, enclosing bounds, footprint/vertex counts and inherited geometry bands before RF timing.', '', '| Domain | Original six IDs, ordered | Appended two IDs | Enclosing footprints6→8 | Vertices6→8 |', '|---|---|---|---:|---:|']
    domains = load(HERE / 'domain-manifest.json')['selected']
    for d in domains:
        a, b = d['paired_geometry']['6C'], d['paired_geometry']['8C']
        lines.append(f"| {d['id']} | {', '.join(d['original_six_ids'])} | {', '.join(d['additional_two_ids'])} | {a['footprints']}→{b['footprints']} | {a['vertices']}→{b['vertices']} |")
    lines += ['', 'Band labels retain the original certification strata; enlarged eight-Cell envelopes are explicitly measured and are not relabelled or reselected after timing. Real co-location remains in dense-certification-2 (the manifest lists each pair). No fabricated coordinates or duplicate IDs are used.', '', 'Historical continuity control: ' + ', '.join(result['historical_comparison']['eight_cell_ids']) + '. Its exact prior fixture bytes are reused and measured separately with W1 RF settings; it matches none of the eight reused primary paired layouts. Historical RF settings and any W1-normalization differences are recorded in [comparison](../scripts/eight-cell-operational-successor/historical-comparison.json).', '', '## 8C-W1 and methodology', '', '120 rays,400m,30dBm,120° beam,2.6/28GHz, normal20/100MHz interference bandwidths, unchanged legacy two-pass search. Selected-network cardinality is eight for Evaluate, Optimize, Interference, retained network explanation and network Building Entry; maps number eight independent single-Cell Simulate calls. Independent Recommendation, Measurement Validation and experiment contracts are retained.', '', 'Real Linux TCP, shipping-equivalent Gin routes, actual middleware/limiter/deadline and uncompressed streamed reads supply primary evidence. The longer monotonic/UTC interval scores requests and groups. A difference over1s invalidates the original observation; no replacement or early stop is allowed. Host `caffeinate -i` prevents automatic idle sleep. HTTP success, complete reads, every request≤45s,≥15s deadline headroom, lifetime cgroup peak≤3GiB, zero oom/oom_kill/max events and all slot/concurrency/background/cancellation/science checks are required.', '', f"Plan: {result['planned_groups']} groups; observed {result['observed_groups']}. Evaluate/Interference each have five repeats per domain/frequency/cardinality; Optimize/Explain/Building Entry each have three. Explanation group timing includes its required Optimize prerequisite, and individual HTTP times remain available in the ledgers. No averaging removes failures.", '', '## Paired six-to-eight measurements', '', 'Wall and CPU ratios below use medians within exact domain/frequency/operation pairs; maximum individual latency and all failures are scored independently. Memory deltas compare observed sampled group maxima, not incremental reservations. Lifetime kernel peak remains the memory gate. No linear N scaling is assumed.', '', '| Domain | GHz | Operation |6C wall s|8C wall s|Wall ratio|6C CPU s|8C CPU s|CPU ratio|Bytes ratio|Sampled cgroup delta MiB|', '|---|---:|---|---:|---:|---:|---:|---:|---:|---:|---:|']
    for p in result['paired_results']:
        lines.append(f"|{p['domain']}|{p['frequency_ghz']}|{p['operation']}|{number(p['6C']['median_group_seconds'])}|{number(p['8C']['median_group_seconds'])}|{number(p['wall_ratio'])}|{number(p['6C']['median_cpu_seconds'])}|{number(p['8C']['median_cpu_seconds'])}|{number(p['cpu_ratio'])}|{number(p['response_byte_ratio'])}|{number(p['sampled_cgroup_current_delta_bytes'] / (1 << 20))}|")
    lines += ['', '### Operational results', '', '|Operation/scenario|Groups|Worst individual s|Largest single bytes|Largest workflow bytes|', '|---|---:|---:|---:|---:|']
    for op, values in result['operations'].items():
        lines.append(f"|{op}|{values['groups']}|{number(values['max_request_seconds'])}|{values['largest_single_response_bytes']}|{values['largest_workflow_response_bytes']}|")
    mem = result['memory']
    lines += ['', f"Worst required eight-Cell request: {number(result['worst_required_eight_cell_request']['elapsed_seconds'] if result['worst_required_eight_cell_request'] else None)}s; minimum deadline headroom {number(result['minimum_deadline_headroom_seconds'])}s. Peak sampled RSS {number(mem['peak_RSS_bytes'] / (1 << 20))}MiB; kernel cgroup peak {number(mem['peak_bytes'] / (1 << 30))}GiB; hard-limit headroom {number(mem['headroom_fraction'] * 100, 2)}%. OOM events: `{mem['events']}`. The conservative peak includes startup, page cache and the extra pre-RF Auto CLI. Stock GC event heap evidence is retained in JSON; no continuous HeapAlloc maximum is inferred.", '', f"True client/native concurrency overlap: {result['concurrency_overlap_pass']}. Normal/sustained background evidence includes uncached native intervals containing every interactive launch, first30s active-worker samples, final-tail overlap and drain barriers. Cancellation cases: {result['cancellation']['passed']}/{result['cancellation']['cases']}; maximum handler-release observation {number(result['cancellation']['max_release_observation_seconds'])}s. Same-client follow-up remaining18 proves cancellation attempt charging and slot reuse; other-client probes also succeed.", '', f"Scientific determinism: {result['science']['stable']}, {result['science']['exact_input_groups']} exact endpoint/request groups; only Building Entry diagnostics.elapsed_ms excluded. Six-Cell preservation: {result['six_cell_preservation']['passed']}; {result['six_cell_preservation']['responses_matching_frozen_W1']} measured responses match frozen W1 evidence.", '', 'Largest contention inflation: `' + json.dumps(result['largest_contention_inflation'], separators=(',', ':')) + '`.', '', 'Search counts use the existing opt-in request-local collector in a separate, non-qualification test executable. No collector is linked/enabled in primary shipping HTTP measurements. Its complete serialized scientific responses must match corresponding real-HTTP results. [Search accounting](../scripts/eight-cell-operational-successor/search-accounting.json) reports proposals, cache hits/misses, RF contribution calculations and spatial counters. Legacy proposals are434 for six and578 for eight; observed cache/geometry counts are recorded per exact fixture.', '', '### Required failures / invalid observations', '', '```json', json.dumps({'capacity_failures': result['capacity_failures'], 'methodology_violations': result['methodology_violations'], 'interruptions': result['interrupted_observations']}, indent=2), '```', '', '## Request budget and product fit', '', 'The policy remains20 protected attempts per ClientIP in an anchored60s fixed window. Every case starts with a fresh real source-IP key. Slot probes are separate declared evidence and are excluded from logical workflow request counts. Header sequences and real admission denials are retained; successful initial workflows contain no duplicates or retries.', '', '|Workflow|6C attempts|8C attempts|6C remaining|8C remaining|', '|---|---:|---:|---:|---:|', '|Evaluate+maps|7|9|13|11|', '|Optimize+maps|7|9|13|11|', '|Full evaluation cycle|15|19|5|1|', '|Evaluate/maps then Optimize/maps|14|18|6|2|', '', '|Domain/fixture|Cells|Scenario|Attempts|First429|Remaining after workflow|Actual first→final s|Window remaining estimate s|Mechanical exact pass|', '|---|---:|---|---:|---:|---:|---:|---:|---|']
    for b in result['budget']['cases']:
        lines.append(f"|{b['fixture']}|{b['cardinality']}|{b['operation']}|{b['attempts']}|{b['first_429_attempt'] or 'none'}|{b['remaining_after_workflow']}|{number(b['elapsed_first_to_final_seconds'])}|{number(b['remaining_window_client_estimate_seconds'])}|{b['mechanical_exact_one_window_pass']}|")
    lines += ['', 'For cycle-boundary scenarios, workflow attempts are15/19; the total includes the two immediate boundary probes. At eight, attempt20 must succeed and21 must return429 with Retry-After and remaining0. Denied requests cannot enter RF handlers: the unchanged middleware aborts before c.Next/global-slot acquisition; process CPU counters and native completion/denial logs corroborate the short rejection path. Deterministic succeeding probes confirm no scientific-state corruption.', '', 'Shared-IP/tab behavior uses separate real TCP connections carrying the same ClientIP, with a distinct-IP probe. The limiter has no tab identity: two nine-call workflows consume18 from the shared bucket, subsequent19/20 succeed and21 denies; the distinct IP retains its independent19 remaining after one request.', '', 'Rapid journeys A/B/D are Evaluate/maps→Interference, Evaluate/maps→Optimize/maps, and Optimize/maps→retained explanation. D reuses the existing Optimize result and adds only one explanation request. C measures the full cycle→Optimize and prospectively declared additional Interference/Evaluate follow-ups to locate denial. The full cycle→Optimize costs20 at eight versus16 at six: the next Interference is attempt21 at eight and17 at six. The absolute deny boundary stays21; eight reaches it earlier in the logical journey.', '', 'First-request and final-response UTC intervals are measured. The unchanged API exposes integer relative RateLimit-Reset/Retry-After, not an exact internal server-admission epoch. Bucket-expiry and remaining-window estimates use the client first-request start and are explicitly labelled; integer header metadata is preserved independently. No server timestamp precision is invented.', '', f"Budget mechanical verdict: **{'PASS' if result['budget']['mechanical_pass'] else 'FAIL / INSUFFICIENT'}**. Product fit: **{result['budget']['product_fit']}**. One residual attempt after the19-call cycle and empirically denied immediate follow-ups are evaluated separately from the arithmetic fact that19 is below20.", '', '## Frontend, persistence and future migration', '', 'Production App callbacks issue one network request followed by the sequential runNetworkSimulationQueue, with one single-Cell map per selected Cell. Optimize maps use returned per-Cell azimuths. User-triggered callbacks, rather than mount effects, start RF work; apiClient adds no automatic RF retry loop. [Disposable UI smoke](../scripts/eight-cell-operational-successor/frontend-smoke.json) replays actual saved HTTP bodies and checks exact frontend payloads and9/9 request counts, marker numbering1–8, selected list, Setup, Results, Solutions, Review, scrolling and reports. Its temporary selection clamp is isolated from production. Literal “two to six” Interference copy is a future review item.', '', '```json', json.dumps(result['presentation_persistence'], indent=2), '```', '', 'V3 network-result-only export/import preserves all eight Cells and scientific optimizer output in the sampled state. Full W1 ray-bearing six/eight samples hit existing expansion/resource guards; full eight with interference also exceeds the encoded-node guard. Rejected variants and sizes/node counts remain reported; no limits are raised. Shipping restore still normalizes eight selected IDs to six. This is not full-ray or general persistence certification.', '', 'The [frozen cardinality inventory](../scripts/eight-cell-operational-successor/cardinality-contracts.json) and [future cap-migration manifest](../scripts/eight-cell-operational-successor/future-cap-migration-manifest.json) classify each location as MUST CHANGE6→8, SHOULD REMAIN INDEPENDENT, DOCUMENTATION ONLY, TEST ONLY or NO CHANGE. Future Recommendation eligibility must remain independent from a larger network clamp; its existing five-Cell contract is not automatically widened. No migration changes are applied.', '', '## Decision, validation and freeze', '', f"Measured operational gates: **{'PASS' if result['measured_operational_gate_pass'] else 'FAIL'}**. Formal qualification: **{'VALID' if result['qualification_valid'] else 'INVALID / INSUFFICIENT'}**; baseline execution and freeze chronology are independently verified. Final direction: **{result['decision']}**. Recommended next action: **{result['next_action']}**.", '', 'Keep the product cap at six for now. Auto remains observation-only and estimator-driven adaptive admission stays paused. Do not add request weights/reservations, change20/60s, promoteW2/W3, raise deployment tiers to rescue A, modify RF/search/Pareto/persistence semantics, or release a new version. VERSION remains0.11.0.', '', 'Baseline and final quality checks:', '', '|Stage|Check|Exit|Required E2E executed|', '|---|---|---:|---|']
    for stage in ['baseline_checks', 'final_checks']:
        for name, record in result[stage].items():
            executed = record.get('required_test_executed', True)
            lines.append(f"|{stage}|{name}|{record['exit_code']}|{executed}|")
    lines += ['', 'Additional protocol coverage includes audit-only cardinality, standard max-six, exact paired layouts, real request construction/counts, missing-reference rejection, native/sustained overlap and final tail, cancellation/slot release, deterministic science and evidence-manifest hashes. [Completion audit](../scripts/eight-cell-operational-successor/completion-audit.json) verifies phases, counts, hashes, preservation and quality. Reproduction tooling and instructions live in [audit directory README](../scripts/eight-cell-operational-successor/README.md).', '', 'Limits: exact frozen scope and finite repeats; shared development VM CPU quotas are not dedicated physical cores; loopback streaming is not a WAN/browser SLO; GC logs sample heap at events; raw local evidence needs separate release-asset/object-storage/LFS archival for permanent publication.', '']
    lines += ['## Required 83-item assessment', '']
    for item in result['required_final_items']:
        lines.append(f"{item['number']}. **{item['label']}:** {item['result']}")
    lines.append('')
    (ROOT / 'docs/eight-cell-operational-budget-successor.md').write_text('\n'.join(lines))
    return result

if __name__ == '__main__':
    value = report()
    print(value['observed_groups'], value['decision'], 'publication_ready', value['publication_ready'])
